    ($SATQ$981aca65$SATQ$, $SATQ$585130f5-a566-4db1-900e-4f8d08cd67e6$SATQ$::uuid, $SATQ$6bdd0966-ec10-4dc2-ada3-07317fe35ded$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 2, $SATQ$Math$SATQ$, $SATQ$Advanced Math$SATQ$, $SATQ$P$SATQ$, $SATQ$P.C.$SATQ$, $SATQ$Nonlinear functions$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, NULL, $SATQ$<p style="text-align: center;"><math alttext="f left parenthesis x right parenthesis equals StartFraction a minus 19 Over x EndFraction plus 5"><mi>f</mi><mfenced><mi>x</mi></mfenced><mo>=</mo><mfrac><mrow><mi>a</mi><mo>-</mo><mrow><mn>19</mn></mrow></mrow><mi>x</mi></mfrac><mo>+</mo><mrow><mn>5</mn></mrow></math></p>
